import { mkdtempSync, rmSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { ContextPruningTracker } from "./src/core/context-pruning/tracker.ts";
import { recoverablePrune } from "./src/core/context-pruning/recovery.ts";
import type { ToolRecord } from "./src/core/context-pruning/types.ts";

const root = mkdtempSync(join(import.meta.dir, ".pruning-check-"));
afterAll(() => rmSync(root, { recursive: true, force: true }));
const output = "é漢🙂 result\\n".repeat(500);
const record = (callId: string, prunedOutput: string | null = null): ToolRecord => ({
  callId, toolName: "code_search", args: { query: "x" },
  originalOutput: output, prunedOutput, timestamp: 1,
});
const run = (tracker: ContextPruningTracker, call: string, body = output, scope = "session") =>
  tracker.process(call, "code_search", { query: "x" }, body, recoverablePrune(root, scope, call, body));

test("persist finalized output, retain original, and reload byte statistics", () => {
  const tracker = new ContextPruningTracker(root);
  run(tracker, "full");
  const second = run(tracker, "short");
  expect(second.modified).toBe(true);
  expect(readFileSync(second.recoveryPath!, "utf8")).toBe(output);
  expect(tracker.getHistory()[1].prunedOutput).toBe(second.output);
  expect(tracker.getHistory()[1].originalOutput).toBe(output);
  expect(tracker.getStats()).toEqual({ totalCalls: 2, prunedCalls: 1,
    totalBytesSaved: Buffer.byteLength(output) - Buffer.byteLength(second.output),
    estimatedContextBytes: Buffer.byteLength(output) + Buffer.byteLength(second.output) });
  const loaded = new ContextPruningTracker(root);
  loaded.loadHistory(JSON.parse(JSON.stringify(tracker.getHistory())));
  expect(loaded.getStats()).toEqual(tracker.getStats());
  expect(run(loaded, "third").output).toContain("callId: full");
});

test("evicting full baseline emits a new full result", () => {
  const tracker = new ContextPruningTracker(root, 2);
  run(tracker, "first");
  run(tracker, "second");
