  expect(run(tracker, "fourth").modified).toBe(false);
  expect(run(tracker, "fifth").output).toContain("callId: fourth");
});

test("select latest matching full result and ignore even matching emitted pointers", () => {
  const tracker = new ContextPruningTracker(root);
  tracker.loadHistory([record("old"), record("new"), record("pointer", output)]);
  expect(run(tracker, "current").output).toContain("callId: new");
